contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 burnAmount) public {
        require(burnAmount <= c.balanceOf(address(this)));

        bool success = c.burn(burnAmount); if (__ESBMC_reverted()) return;

        assert(success);
    }

    receive() external payable {}
}

