pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 burnAmount) internal {
        vm.assume(burnAmount <= c.balanceOf(address(this)));
        bool success;
        try c.burn(burnAmount) returns (bool __r) { success = __r; } catch { return; }
        assertTrue(success);
    }

    function testFuzz_run(uint256 burnAmount) public {
        _run(burnAmount);
    }

    receive() external payable {}
}
